bool telemetry_init(const TelemetryConfig* config) {
    if (!config) return false;
    
    memcpy(&s_config, config, sizeof(TelemetryConfig));
    
    // Create JSON payload object
    if (s_payload) {
        cJSON_Delete(s_payload);
    }
    s_payload = cJSON_CreateObject();
    
    ESP_LOGI(TAG, "Transport: %s", 
             s_config.transport == TELEMETRY_TRANSPORT_UDP ? "UDP" :
             s_config.transport == TELEMETRY_TRANSPORT_TCP ? "TCP" :
             s_config.transport == TELEMETRY_TRANSPORT_HTTP ? "HTTP" : "UART");
    ESP_LOGI(TAG, "Target: %s:%d", s_config.host, s_config.port);
    ESP_LOGI(TAG, "Interval: %lu ms", s_config.send_interval_ms);
    
    // UDP socket is created lazily on first send to avoid calling socket()
    // before the TCP/IP stack is initialized (WiFi not yet connected).
    s_udp_socket = -1;
    
    s_initialized = true;
    return true;
}

