#include "pal/pal_websocket.h"

static bool ws_ensure_connected()
{
    if (pal_ws_is_connected()) return true;
    if (!s_ws_initialized) {
        char uri[192];
        snprintf(uri, sizeof(uri), "ws://%s:%d/ws/device/%s",
                 s_config.host, s_config.port, TELEMETRY_MCU_ID);
        pal_ws_config_t ws_cfg = { .uri = uri, .subprotocol = NULL, .ping_interval_ms = 30000 };
        pal_ws_init(&ws_cfg);
        s_ws_initialized = true;
    }
    pal_ws_connect();
    vTaskDelay(pdMS_TO_TICKS(500));
    return pal_ws_is_connected();
}

static bool send_websocket()
{
    if (!ws_ensure_connected()) {
        ESP_LOGW(TAG, "WS not connected");
        return false;
    }

    cJSON *frame = cJSON_CreateObject();
    cJSON_AddStringToObject(frame, "type", "telemetry");
    cJSON_AddStringToObject(frame, "mcu_id", TELEMETRY_MCU_ID);
    cJSON_AddNumberToObject(frame, "timestamp", (double)get_millis());
    cJSON *values = cJSON_Duplicate(s_payload, true);
    cJSON_AddItemToObject(frame, "values", values);

    char *json_str = cJSON_PrintUnformatted(frame);
    cJSON_Delete(frame);
    if (!json_str) return false;

    int rc = pal_ws_send_text(json_str, strlen(json_str));
    bool ok = (rc == 0);
    if (ok) ESP_LOGD(TAG, "WS sent %d bytes", (int)strlen(json_str));
    else    ESP_LOGE(TAG, "WS send failed");
    cJSON_free(json_str);
    return ok;
}

