static bool send_udp() {
    if (strlen(s_config.host) == 0 || s_config.port == 0) {
        ESP_LOGE(TAG, "UDP not configured");
        return false;
    }
    // Lazy socket creation — deferred from telemetry_init to ensure TCP/IP stack is ready
    if (s_udp_socket < 0) {
        s_udp_socket = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
        if (s_udp_socket < 0) {
            ESP_LOGE(TAG, "Failed to create UDP socket (TCP/IP stack may not be ready)");
            return false;
        }
        ESP_LOGI(TAG, "UDP socket created (fd=%d)", s_udp_socket);
    }
    
    char* json_str = cJSON_PrintUnformatted(s_payload);
    if (!json_str) {
        ESP_LOGE(TAG, "Failed to serialize JSON");
        return false;
    }
    
    struct sockaddr_in dest_addr;
    dest_addr.sin_addr.s_addr = inet_addr(s_config.host);
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(s_config.port);
    
    int err = sendto(s_udp_socket, json_str, strlen(json_str), 0,
                     (struct sockaddr*)&dest_addr, sizeof(dest_addr));
    
    bool success = (err > 0);
    if (success) {
        ESP_LOGD(TAG, "UDP sent: %s", json_str);
    } else {
        ESP_LOGE(TAG, "UDP send failed: %d", err);
    }
    
    cJSON_free(json_str);
    return success;
}

static bool send_http() {
    if (strlen(s_config.host) == 0 || s_config.port == 0) {
        ESP_LOGE(TAG, "HTTP not configured");
        return false;
    }
    
    cJSON* frame = NULL;
    
    if (s_stream_active) {
        /* Protocol-aware data frame with transaction context */
        frame = cJSON_CreateObject();
        cJSON_AddStringToObject(frame, "frame_role", "data");
        cJSON_AddStringToObject(frame, "mcu_id", TELEMETRY_MCU_ID);
        cJSON_AddNumberToObject(frame, "timestamp", (double)get_millis());
        
        /* Nest sensor values under "values" key */
        cJSON* values = cJSON_Duplicate(s_payload, true);
        cJSON_AddItemToObject(frame, "values", values);
        
        /* Add per-signal sequence numbers */
        s_stream_sequence++;
        cJSON* sequences = cJSON_CreateObject();
        cJSON_AddItemToObject(frame, "sequences", sequences);
    } else {
        /* Legacy flat payload (backward compatible) */
        frame = cJSON_Duplicate(s_payload, true);
        cJSON_AddStringToObject(frame, "mcu_id", TELEMETRY_MCU_ID);
    }
    
    char* json_str = cJSON_PrintUnformatted(frame);
    cJSON_Delete(frame);
    
    if (!json_str) {
        ESP_LOGE(TAG, "Failed to serialize JSON");
        return false;
    }
    
    char url[256];
    bool use_tls = (s_config.port == 443);
    const char *scheme = use_tls ? "https" : "http";
    bool standard_port = (s_config.port == 443 || s_config.port == 80);
    if (standard_port) {
        snprintf(url, sizeof(url), "%s://%s%s", scheme, s_config.host, s_config.http_endpoint);
    } else {
        snprintf(url, sizeof(url), "%s://%s:%d%s", scheme, s_config.host, s_config.port,
                 s_config.http_endpoint);
    }
    
    esp_http_client_config_t config = {};
    config.url = url;
    config.method = HTTP_METHOD_POST;
    config.timeout_ms = 10000;
    if (use_tls) {
        config.crt_bundle_attach = esp_crt_bundle_attach;
    }
    
    esp_http_client_handle_t client = esp_http_client_init(&config);
    if (!client) {
        ESP_LOGE(TAG, "Failed to init HTTP client");
        cJSON_free(json_str);
        return false;
    }
    
    esp_http_client_set_header(client, "Content-Type", "application/json");
    esp_http_client_set_header(client, "X-MCU-ID", TELEMETRY_MCU_ID);
    esp_http_client_set_post_field(client, json_str, strlen(json_str));
    
    esp_err_t err = esp_http_client_perform(client);
    int status = esp_http_client_get_status_code(client);
    
    bool success = (err == ESP_OK && status >= 200 && status < 300);
    if (success) {
        ESP_LOGD(TAG, "HTTP sent: %s (status %d)", json_str, status);
    } else {
        ESP_LOGE(TAG, "HTTP failed: err=%s, status=%d", esp_err_to_name(err), status);
    }
    
    esp_http_client_cleanup(client);
    cJSON_free(json_str);
    return success;
}

bool telemetry_is_ready(void) {
    if (!s_initialized || !s_config.enabled) {
        return false;
    }
    
    // For network transports, check WiFi
    if (s_config.transport == TELEMETRY_TRANSPORT_UDP ||
        s_config.transport == TELEMETRY_TRANSPORT_TCP ||
        s_config.transport == TELEMETRY_TRANSPORT_HTTP ||
        s_config.transport == TELEMETRY_TRANSPORT_WEBSOCKET) {
        return wifi_station_is_connected();
    }
    
    return true;
}

bool telemetry_send_now(void) {
    if (!s_initialized) {
        return false;
    }
    
    if (!telemetry_is_ready()) {
        ESP_LOGW(TAG, "Not ready (WiFi not connected?)");
        return false;
    }
    
    /* Auto-start stream on first successful send (HTTP transport only) */
    if (s_config.transport == TELEMETRY_TRANSPORT_HTTP && !s_stream_active) {
        telemetry_stream_start();
    }
    
    bool success = false;
    
    switch (s_config.transport) {
    case TELEMETRY_TRANSPORT_UDP:
        success = send_udp();
        break;
    case TELEMETRY_TRANSPORT_TCP:
        ESP_LOGW(TAG, "TCP not implemented");
        break;
    case TELEMETRY_TRANSPORT_UART:
        {
            char* json_str = cJSON_PrintUnformatted(s_payload);
            if (json_str) {
                printf("%s\n", json_str);
                cJSON_free(json_str);
                success = true;
            }
            // Also forward to backend via HTTP if WiFi is connected and
            // a backend host is configured (dual-send: UART + HTTP)
            if (s_config.host[0] != '\0' && wifi_station_is_connected()) {
                send_http();
            }
        }
        break;
    case TELEMETRY_TRANSPORT_HTTP:
        success = send_http();
        break;
    case TELEMETRY_TRANSPORT_WEBSOCKET:
        success = send_websocket();
        break;
    default:
        break;
    }
    
    if (success) {
        s_send_count++;
        s_last_send_ok = true;
        s_consecutive_failures = 0;
        s_backoff_ms = 0;
    } else {
        s_error_count++;
        s_last_send_ok = false;
        s_consecutive_failures++;
        if (s_consecutive_failures <= 3) {
            s_backoff_ms = s_config.send_interval_ms;
        } else if (s_consecutive_failures <= 10) {
            s_backoff_ms = s_config.send_interval_ms * 5;
        } else {
            s_backoff_ms = 30000;
        }
    }
    
    return success;
}

void telemetry_process(void) {
    if (!s_config.enabled || !s_initialized) {
        return;
    }
    
    uint32_t now = get_millis();
    uint32_t interval = s_config.send_interval_ms + s_backoff_ms;
    if (now - s_last_send_time >= interval) {
        s_last_send_time = now;
        telemetry_send_now();
    }
}

