// Stream protocol functions

static bool send_stream_control(const char* json_str) {
    if (strlen(s_config.host) == 0 || s_config.port == 0) {
        ESP_LOGE(TAG, "HTTP not configured");
        return false;
    }
    
    char url[256];
    bool use_tls = (s_config.port == 443);
    const char *scheme = use_tls ? "https" : "http";
    bool standard_port = (s_config.port == 443 || s_config.port == 80);
    if (standard_port) {
        snprintf(url, sizeof(url), "%s://%s%s", scheme, s_config.host, TELEMETRY_STREAM_ENDPOINT);
    } else {
        snprintf(url, sizeof(url), "%s://%s:%d%s", scheme, s_config.host, s_config.port,
                 TELEMETRY_STREAM_ENDPOINT);
    }
    
    esp_http_client_config_t config = {};
    config.url = url;
    config.method = HTTP_METHOD_POST;
    config.timeout_ms = 10000;
    if (use_tls) {
        config.crt_bundle_attach = esp_crt_bundle_attach;
    }
    
    esp_http_client_handle_t client = esp_http_client_init(&config);
    if (!client) {
        ESP_LOGE(TAG, "Failed to init HTTP client for stream control");
        return false;
    }
    
    esp_http_client_set_header(client, "Content-Type", "application/json");
    esp_http_client_set_post_field(client, json_str, strlen(json_str));
    
    esp_err_t err = esp_http_client_perform(client);
    int status = esp_http_client_get_status_code(client);
    
    bool success = (err == ESP_OK && status >= 200 && status < 300);
    if (!success) {
        ESP_LOGE(TAG, "Stream control failed: err=%s, status=%d", esp_err_to_name(err), status);
    }
    
    esp_http_client_cleanup(client);
    return success;
}

/**
 * Send a per-variable start_stream frame with retry logic.
 */
static bool __attribute__((unused)) send_start_stream_for_variable(const char* variable_id, const char* var_name,
                                           const char* var_type, const char* frame_name,
                                           uint32_t max_retries) {
    cJSON* root = cJSON_CreateObject();
    cJSON_AddStringToObject(root, "frame_role", "start_stream");
    cJSON_AddStringToObject(root, "frame_name", frame_name);
    cJSON_AddStringToObject(root, "mcu_id", TELEMETRY_MCU_ID);
    cJSON_AddStringToObject(root, "protocol_version", TELEMETRY_PROTOCOL_VERSION);
    cJSON_AddStringToObject(root, "schema_hash", TELEMETRY_SCHEMA_HASH);

    cJSON* signals = cJSON_AddArrayToObject(root, "signals");
    cJSON* sig_obj = cJSON_CreateObject();
    cJSON_AddStringToObject(sig_obj, "variable_id", variable_id);
    cJSON_AddStringToObject(sig_obj, "name", var_name);
    cJSON_AddStringToObject(sig_obj, "type", var_type);
    cJSON_AddNumberToObject(sig_obj, "frequency_ms", s_config.send_interval_ms);
    cJSON_AddItemToArray(signals, sig_obj);

    char* json_str = cJSON_PrintUnformatted(root);
    cJSON_Delete(root);

    if (!json_str) {
        ESP_LOGE(TAG, "Failed to build start_stream JSON for %s", var_name);
        return false;
    }

    bool ok = false;
    for (uint32_t attempt = 0; attempt <= max_retries; attempt++) {
        if (send_stream_control(json_str)) {
            ok = true;
            ESP_LOGI(TAG, "Frame sent: %s (signal: %s)", frame_name, var_name);
            break;
        }
        if (attempt < max_retries) {
            ESP_LOGW(TAG, "Retry %lu/%lu for %s", (unsigned long)(attempt + 1),
                     (unsigned long)max_retries, frame_name);
            vTaskDelay(pdMS_TO_TICKS(500));
        }
    }

    cJSON_free(json_str);
    return ok;
}

/**
 * Send a per-variable stop_stream frame.
 */
static bool __attribute__((unused)) send_stop_stream_for_variable(const char* variable_id, const char* frame_name) {
    cJSON* root = cJSON_CreateObject();
    cJSON_AddStringToObject(root, "frame_role", "stop_stream");
    cJSON_AddStringToObject(root, "frame_name", frame_name);
    cJSON_AddStringToObject(root, "mcu_id", TELEMETRY_MCU_ID);

    cJSON* signals = cJSON_AddArrayToObject(root, "signals");
    cJSON_AddItemToArray(signals, cJSON_CreateString(variable_id));

    char* json_str = cJSON_PrintUnformatted(root);
    cJSON_Delete(root);

    if (!json_str) {
        return false;
    }

    bool ok = send_stream_control(json_str);
    cJSON_free(json_str);

    if (ok) {
        ESP_LOGI(TAG, "Frame sent: %s", frame_name);
    }
    return ok;
}

bool telemetry_stream_start(void) {
    if (!s_initialized || !telemetry_is_ready()) {
        ESP_LOGW(TAG, "Cannot start stream - not ready");
        return false;
    }

    bool all_ok = true;

    /* Send per-variable start_stream frames using named frames from protocol definition */
    /* Fallback: send all signals in one bulk start_stream (no per-frame definitions) */
    cJSON* root = cJSON_CreateObject();
    cJSON_AddStringToObject(root, "frame_role", "start_stream");
    cJSON_AddStringToObject(root, "mcu_id", TELEMETRY_MCU_ID);
    cJSON_AddStringToObject(root, "protocol_version", TELEMETRY_PROTOCOL_VERSION);
    cJSON_AddStringToObject(root, "schema_hash", TELEMETRY_SCHEMA_HASH);
    cJSON* signals = cJSON_AddArrayToObject(root, "signals");
    (void)signals;
    char* json_str = cJSON_PrintUnformatted(root);
    cJSON_Delete(root);
    if (json_str) {
        all_ok = send_stream_control(json_str);
        cJSON_free(json_str);
    }

    if (all_ok) {
        s_stream_active = true;
        s_stream_sequence = 0;
        ESP_LOGI(TAG, "All streams started (protocol=%s, schema=%s)",
                 TELEMETRY_PROTOCOL_VERSION, TELEMETRY_SCHEMA_HASH);
    }

    return all_ok;
}

bool telemetry_stream_stop(void) {
    if (!s_stream_active) {
        return true;
    }

    bool all_ok = true;

    /* Fallback: send bulk stop_stream */
    cJSON* root = cJSON_CreateObject();
    cJSON_AddStringToObject(root, "frame_role", "stop_stream");
    cJSON_AddStringToObject(root, "mcu_id", TELEMETRY_MCU_ID);
    cJSON* signals = cJSON_AddArrayToObject(root, "signals");
    (void)signals;
    char* json_str = cJSON_PrintUnformatted(root);
    cJSON_Delete(root);
    if (json_str) {
        all_ok = send_stream_control(json_str);
        cJSON_free(json_str);
    }

    if (all_ok) {
        s_stream_active = false;
        ESP_LOGI(TAG, "All streams stopped");
    }

    return all_ok;
}

bool telemetry_stream_is_active(void) {
    return s_stream_active;
}

